const NN=["C","D♭","D","E♭","E","F","G♭","G","A♭","A","B♭","B"];let AC=null;
function tone(m,d){try{AC=AC||new(window.AudioContext||window.webkitAudioContext)();const o=AC.createOscillator(),g=AC.createGain(),t=AC.currentTime;o.type="triangle";o.frequency.value=440*Math.pow(2,(m-69)/12);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.35,t+.02);g.gain.exponentialRampToValueAtTime(.0001,t+(d||.7));o.connect(g).connect(AC.destination);o.start(t);o.stop(t+(d||.7)+.05)}catch(e){}}
