 if(g$("sp")){const upd=()=>{const r=+g$("sr").value,iv=g$("sst").value.split(",").map(Number),nm=iv.map(v=>NN[(r+v)%12]),st=[];for(let i=1;i<iv.length;i++){const d=iv[i]-iv[i-1];st.push(d==1?"H":d==2?"W":"W+H")}g$("so").textContent=nm.join(" ")+" · steps: "+st.join(" ")};g$("sr").onchange=g$("sst").onchange=upd;upd();g$("sp").onclick=()=>{const r=+g$("sr").value;g$("sst").value.split(",").map(Number).forEach((v,i)=>setTimeout(()=>tone(60+r+v,.45),i*340))}}
